import csv,json,hashlib
from pathlib import Path
from decimal import Decimal as D
from collections import defaultdict,deque
ROOT=Path('/Users/mac/.codex/worktrees/weekly-no-half-r-20261022/fian')
L=ROOT/'research/lines/futures_weekly_formal_no_half_r'
P=L/'outputs/N_attempt002'
R=L/'outputs/stage028_2015_2020_trade_audit'
def read(p): return list(csv.DictReader(p.open()))
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
source_paths=[P/'trades.csv',P/'effective_parameters.json',P/'execution_clock.csv']
pre={str(p):sha(p) for p in source_paths}
settings=json.loads((P/'effective_parameters.json').read_text())
clock={r['trade_id']:r for r in read(P/'execution_clock.csv')}
trades=read(P/'trades.csv'); assert len(clock)==len(trades)==934
assert len({r['trade_id'] for r in trades})==len(trades)
queues=defaultdict(deque); active={}; episodes=[]; segments=[]
for t in trades:
 sym=t['vt_symbol']; tid=t['trade_id']; date=clock[tid]['trading_date']; q=D(t['volume']); price=D(t['price']); sz=D(str(settings['sizes'][sym])); slip=D(str(settings['slippages'][sym])); rate=D(str(settings['rates'][sym])); cost=slip*q*sz+abs(price*q*sz)*rate
 assert date==t['trading_date']; assert D(clock[tid]['price'])==price; assert D(clock[tid]['volume'])==q
 direction=1 if t['direction']=='多' else -1
 if t['offset']=='开':
  if sym not in active:
   e={'episode_id':f'NE{len(episodes)+1:04d}','vt_symbol':sym,'direction':direction,'entry_date':date,'entry_trade_id':tid,'exit_date':None,'net_pnl':D(0),'fill_ids':[],'balance':D(0)}; episodes.append(e); active[sym]=e
  e=active[sym]; assert e['direction']==direction
  e['fill_ids'].append(tid);e['balance']+=q
  queues[sym].append({'q':q,'price':price,'direction':direction,'id':tid,'date':date,'unit_cost':cost/q,'episode':e})
 else:
  e=active[sym]; assert e['direction']==-direction;e['fill_ids'].append(tid);e['balance']-=q
  left=q
  while left:
   lot=queues[sym][0]; n=min(left,lot['q']); gross=(price-lot['price'])*n*sz*lot['direction']; net=gross-n*lot['unit_cost']-cost*n/q
   s={'episode_id':e['episode_id'],'vt_symbol':sym,'entry_trade_id':lot['id'],'exit_trade_id':tid,'entry_date':lot['date'],'exit_date':date,'volume':n,'net_pnl':net};segments.append(s);e['net_pnl']+=net;left-=n;lot['q']-=n
   if not lot['q']:queues[sym].popleft()
  if not e['balance']:e['exit_date']=date;del active[sym]
 assert active.get(sym,{}).get('balance',D(0))>=0
origseg=read(R/'full_N_closed_fifo_segments.csv');assert len(origseg)==len(segments)==471
origep=read(R/'full_N_contract_episode_inventory.csv');assert len(origep)==len(episodes)==463
slookup={(s['entry_trade_id'],s['exit_trade_id'],s['volume']):s for s in segments};assert len(slookup)==471
for row in origseg:
 key=row['entry_trade_id'],row['exit_trade_id'],D(row['quantity']);s=slookup[key]
 assert abs(s['net_pnl']-D(row['net_pnl']))<D('0.000001'),(key,s['net_pnl'],row['net_pnl'])
 assert s['episode_id']==row['episode_id'];assert s['exit_date']==row['exit_date']; assert s['entry_date']==row['entry_date']
elookup={e['episode_id']:e for e in episodes}
for row in origep:
 e=elookup[row['episode_id']]
 assert e['vt_symbol']==row['vt_symbol'];assert e['fill_ids']==json.loads(row['fill_trade_ids'])
 assert e['entry_date']==row['entry_date'];assert (e['exit_date'] or '')==row['exit_date']
 assert abs(e['net_pnl']-D(row['realized_closed_net_pnl']))<D('0.000001')
def stat(rows):
 vals=[r['net_pnl'] for r in rows];wins=[n for n in vals if n>0];loss=[-n for n in vals if n<0]
 return {'count':len(vals),'win':len(wins),'loss':len(loss),'flat':len(vals)-len(wins)-len(loss),'win_rate_pct':float(D(len(wins))/len(vals)*100),'average_win':float(sum(wins)/len(wins)),'average_loss_abs':float(sum(loss)/len(loss)),'payoff':float((sum(wins)/len(wins))/(sum(loss)/len(loss))),'profit_factor':float(sum(wins)/sum(loss)),'net_pnl':float(sum(vals))}
results={}
for end in ('2019-12-31','2020-12-31'):
 fills=[t for t in trades if '2015-01-01'<=t['trading_date']<=end]
 results[end]={'fills':len(fills),'open_fills':sum(t['offset']=='开' for t in fills),'close_fills':sum(t['offset']!='开' for t in fills)}
 for scope in ('exit_date','entry_date'):
  results[end][scope]={'fifo':stat([s for s in segments if '2015-01-01'<=s[scope]<=end]),'episodes':stat([e for e in episodes if e['exit_date'] and '2015-01-01'<=e[scope]<=end])}
post={str(p):sha(p) for p in source_paths};assert pre==post
out={'method':'Independent Decimal reconstruction from raw trades, settings, execution_clock; no replay/report imports','full_counts':{'fills':len(trades),'segments':len(segments),'episodes':len(episodes),'closed_episodes':sum(e['exit_date'] is not None for e in episodes),'terminal_active':len(active)},'statistics':results,'checks':{'all471segments_match':True,'all463episodes_match':True,'input_sha_unchanged':pre==post},'source_sha256':pre,'script_sha256':sha(Path(__file__))}
Path('/private/tmp/stage028_combined_review_stats_result.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
print(json.dumps(out,ensure_ascii=False,indent=2))

